      (entries) => {
        if (!entries.some((entry) => entry.isIntersecting)) {
          return;
        }

        observer?.disconnect();
        activateModel();
      },
      { rootMargin: '120px 0px' },
    );

    observer.observe(host);

    return () => {
      disposed = true;
      observer?.disconnect();
      cancelIdleTask();
    };
