  const w = window as ViewerWindow;

  if (w.Live2DCubismCore) {
    return Promise.resolve();
  }

  if (w.__viewerLive2DScriptPromise) {
    return w.__viewerLive2DScriptPromise;
  }

  w.__viewerLive2DScriptPromise = new Promise<void>((resolve, reject) => {
    const existing = document.querySelector<HTMLScriptElement>(
      `script[data-viewer-live2d-core="${src}"]`,
    );

    if (existing?.dataset.loaded === 'true') {
      resolve();
      return;
    }

    if (existing) {
      existing.addEventListener('load', () => resolve(), { once: true });
      existing.addEventListener(
        'error',
        () => reject(new Error(`Failed to load script: ${src}`)),
        { once: true },
      );
      return;
    }

    const script = document.createElement('script');
    script.src = src;
    script.async = true;
    script.dataset.viewerLive2dCore = src;
    script.onload = () => {
      script.dataset.loaded = 'true';
      resolve();
    };
    script.onerror = () => reject(new Error(`Failed to load script: ${src}`));
    document.head.appendChild(script);
  });

  return w.__viewerLive2DScriptPromise;
}

export function Live2DHeroModel() {
  const language = useProductLanguage();
  const hostRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLDivElement | null>(null);
  const [shouldLoadModel, setShouldLoadModel] = useState(import.meta.env.MODE === 'test');
  const [modelState, setModelState] = useState<'idle' | 'loading' | 'ready' | 'error'>(
    import.meta.env.MODE === 'test' ? 'ready' : 'idle',
  );

  useEffect(() => {
    if (import.meta.env.MODE === 'test') {
      return;
    }

    const host = hostRef.current;
    if (!host) {
      return;
    }

    let disposed = false;
    let cancelIdleTask: () => void = () => undefined;

    const activateModel = () => {
      if (disposed) {
        return;
      }

      setModelState((current) => (current === 'ready' ? current : 'loading'));
      cancelIdleTask = scheduleIdleTask(
        () => {
          if (!disposed) {
            setShouldLoadModel(true);
          }
        },
        { timeout: 1200, fallbackDelayMs: 140 },
      );
    };

    if (typeof IntersectionObserver === 'undefined') {
      activateModel();
      return () => {
        disposed = true;
        cancelIdleTask();
      };
    }

    const observer = new IntersectionObserver(
      (entries) => {
        if (!entries.some((entry) => entry.isIntersecting)) {
          return;
        }

        observer.disconnect();
        activateModel();
      },
      { rootMargin: '120px 0px' },
    );

    observer.observe(host);

    return () => {
      disposed = true;
      observer.disconnect();
      cancelIdleTask();
    };
  }, []);

  useEffect(() => {
    if (!shouldLoadModel) {
      return;
    }

    if (import.meta.env.MODE === 'test') {
      setModelState('ready');
      return;
    }

    const host = hostRef.current;
    const canvasHost = canvasRef.current;
    if (!host || !canvasHost) {
      return;
    }
    const hostElement: HTMLDivElement = host;
    const canvasHostElement: HTMLDivElement = canvasHost;

    let disposed = false;
    let app: import('pixi.js-legacy').Application | undefined;
    let model:
      | (import('pixi-live2d-display/cubism4').Live2DModel & {
          anchor: { set: (x: number, y?: number) => void };
        })
      | undefined;
    let resizeObserver: ResizeObserver | undefined;
    let onPointerMove: ((event: PointerEvent) => void) | undefined;
    let onPointerLeave: (() => void) | undefined;

    async function mountModel() {
      await loadScriptOnce(CORE_SCRIPT_URL);

      const PIXI = await import('pixi.js-legacy');
      (window as ViewerWindow).PIXI = PIXI;

      const { Live2DModel } = await import('pixi-live2d-display/cubism4');

      if (disposed || !hostElement.isConnected) {
        return;
      }

      app = new PIXI.Application({
        resizeTo: hostElement,
        autoDensity: true,
        antialias: true,
        backgroundAlpha: 0,
      });

      canvasHostElement.replaceChildren(app.view);

      model = await Live2DModel.from(MODEL_URL, {
        autoInteract: false,
      });

      if (disposed || !app) {
        model.destroy();
        return;
      }

      model.anchor.set(0.5, 1);
      model.interactive = true;
      model.buttonMode = false;
      model.cursor = 'pointer';

      model.on('hit', (hitAreas: string[]) => {
        if (hitAreas.some((area) => area.toLowerCase() === 'body')) {
          void model?.motion('TapBody');
        }
      });

      app.stage.addChild(model);

      const fitModel = () => {
        if (!model) {
          return;
        }

        const width = hostElement.clientWidth;
        const height = hostElement.clientHeight;

        if (!width || !height) {
          return;
        }

        model.scale.set(1);
        const baseWidth = model.width || 1;
        const baseHeight = model.height || 1;
        const scale = Math.min((width * 1.12) / baseWidth, (height * 1.06) / baseHeight);

        model.scale.set(scale);
        model.x = width * 0.4;
        model.y = height * 0.995;
      };

      fitModel();
      void model.motion('Idle');
      setModelState('ready');

      if (typeof ResizeObserver !== 'undefined') {
        resizeObserver = new ResizeObserver(() => {
          fitModel();
        });
        resizeObserver.observe(hostElement);
      }

      onPointerMove = (event: PointerEvent) => {
        if (!model) {
          return;
        }

        const rect = hostElement.getBoundingClientRect();
        model.focus(event.clientX - rect.left, event.clientY - rect.top);
      };

      onPointerLeave = () => {
        if (!model) {
          return;
        }

        model.focus(hostElement.clientWidth * 0.5, hostElement.clientHeight * 0.52, true);
      };

      hostElement.addEventListener('pointermove', onPointerMove);
      hostElement.addEventListener('pointerleave', onPointerLeave);
    }

    void mountModel().catch(() => {
      if (!disposed) {
        setModelState('error');
      }
    });

    return () => {
      disposed = true;

      if (onPointerMove) {
        hostElement.removeEventListener('pointermove', onPointerMove);
      }
      if (onPointerLeave) {
        hostElement.removeEventListener('pointerleave', onPointerLeave);
      }

      resizeObserver?.disconnect();
      model?.destroy({ children: true });
      app?.destroy(true, { children: true });
    };
  }, [shouldLoadModel]);

  return (
    <div ref={hostRef} className="relative h-full w-full overflow-visible">
      <div className="pointer-events-none absolute bottom-[6%] left-[10%] h-8 w-[56%] rounded-full bg-[radial-gradient(circle,rgba(114,93,73,0.20),rgba(114,93,73,0)_72%)] blur-xl" />
      <div
        className={[
          'pointer-events-none absolute inset-0 z-0 flex items-end justify-center transition-opacity duration-300',
          modelState === 'ready' ? 'opacity-0' : 'opacity-100',
        ].join(' ')}
        aria-hidden={modelState === 'ready'}
      >
        <div className="viewer-live2d-placeholder-shell">
          <span className="viewer-live2d-placeholder__aura" />
          <span className="viewer-live2d-placeholder__orbit viewer-live2d-placeholder__orbit--outer" />
          <span className="viewer-live2d-placeholder__orbit viewer-live2d-placeholder__orbit--inner" />
          <span className="viewer-live2d-placeholder__core" />
        </div>
      </div>
      <div
        ref={canvasRef}
        className={[
          'absolute inset-0 z-10 transition-opacity duration-300',
          modelState === 'ready' ? 'opacity-100' : 'opacity-0',
        ].join(' ')}
      />
      {modelState === 'loading' ? (
        <div className="pointer-events-none absolute left-1/2 top-4 z-20 -translate-x-1/2 rounded-full border border-[#e0d4c1] bg-[rgba(255,252,247,0.82)] px-3 py-1 text-[0.72rem] font-semibold text-[#8a7d71] shadow-[0_10px_24px_rgba(90,70,50,0.08)]">
          {language === 'zh-CN' ? '角色加载中…' : 'Loading companion…'}
        </div>
      ) : null}
      {modelState === 'error' ? (
        <div className="pointer-events-none absolute left-1/2 top-4 z-20 -translate-x-1/2 rounded-full border border-[#e0d4c1] bg-[rgba(255,252,247,0.82)] px-3 py-1 text-[0.72rem] font-semibold text-[#8a7d71] shadow-[0_10px_24px_rgba(90,70,50,0.08)]">
          {language === 'zh-CN' ? '角色暂时不可用' : 'Companion unavailable'}
        </div>
      ) : null}
    </div>
  );
}

import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useAppDispatch, useAppSelector } from '@/store';
import { updateMetadata } from '@/store/editorSlice';
import { FormField, Input, Select, Textarea } from '../FormField';

const schema = z.object({
  title: z.string().min(1, 'Title is required'),
  description: z.string().optional(),
  difficulty_level: z.enum(['beginner', 'intermediate', 'advanced']).optional(),
  estimated_minutes: z.coerce.number().min(0).optional(),
  tags: z.string().optional(), // comma-separated in UI
});

type FormValues = z.infer<typeof schema>;

export function MetadataPanel() {
  const dispatch = useAppDispatch();
  const metadata = useAppSelector((s) => s.editor.draft?.metadata);

  const { register, watch, reset } = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      title: metadata?.title ?? '',
      description: metadata?.description ?? '',
      difficulty_level: metadata?.difficulty_level,
      estimated_minutes: metadata?.estimated_minutes,
      tags: metadata?.tags?.join(', ') ?? '',
    },
  });

  useEffect(() => {
    reset({
      title: metadata?.title ?? '',
      description: metadata?.description ?? '',
      difficulty_level: metadata?.difficulty_level,
      estimated_minutes: metadata?.estimated_minutes,
      tags: metadata?.tags?.join(', ') ?? '',
    });
  }, []); // eslint-disable-line react-hooks/exhaustive-deps -- 仅在挂载时初始化表单，metadata 后续变更由编辑器 store 管理

  useEffect(() => {
    const sub = watch((values) => {
      dispatch(
        updateMetadata({
          title: values.title ?? '',
          description: values.description ?? undefined,
          difficulty_level: values.difficulty_level ?? undefined,
          estimated_minutes: values.estimated_minutes
            ? Number(values.estimated_minutes)
            : undefined,
          tags: values.tags
            ? values.tags
                .split(',')
                .map((t) => t.trim())
                .filter(Boolean)
            : undefined,
        }),
      );
    });
    return () => sub.unsubscribe();
  }, [watch, dispatch]);

  if (!metadata) return null;

  return (
    <div className="space-y-4">
      <FormField label="Course title">
        <Input {...register('title')} placeholder="e.g. Introduction to Python" />
      </FormField>

      <FormField label="Description">
        <Textarea
          rows={3}
          {...register('description')}
          placeholder="What will learners achieve?"
        />
      </FormField>

      <FormField label="Difficulty">
        <Select {...register('difficulty_level')}>
          <option value="">Not set</option>
          <option value="beginner">Beginner</option>
          <option value="intermediate">Intermediate</option>
          <option value="advanced">Advanced</option>
        </Select>
      </FormField>

      <FormField label="Estimated duration (minutes)">
        <Input
          type="number"
          min={0}
          step={5}
          {...register('estimated_minutes')}
          placeholder="e.g. 30"
        />
      </FormField>

      <FormField label="Tags (comma-separated)">
        <Input
          {...register('tags')}
          placeholder="e.g. python, algorithms, beginner"
        />
      </FormField>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { ChevronDownIcon, MagnifyingGlassIcon, PlusIcon } from '@radix-ui/react-icons';
import { useAppDispatch, useAppSelector } from '@/store';
import { openDraft, addLesson, addPage, addBlock, selectBlock } from '@/store/editorSlice';
import { EditorHeader } from './EditorHeader';
import { BlockCanvas } from './canvas/BlockCanvas';
import { PropertyPanel } from './properties/PropertyPanel';
import { PreviewMode } from './preview/PreviewMode';
import { nanoid } from '@/lib/nanoid';
import { uuid } from '@/lib/uuid';
import { BLOCK_CATEGORIES, BLOCK_META } from './blockRegistry';
import { getDefaultVisibilityRule } from './blockVisibility';
import type { Course } from '@primoria/schema';
import type { BlockType } from '@primoria/schema';
import './editor.css';

interface EditorLayoutProps {
  remoteCourse: Course;
}

export function EditorLayout({ remoteCourse }: EditorLayoutProps) {
  const dispatch = useAppDispatch();
  const draft = useAppSelector((s) => s.editor.draft);
  const previewMode = useAppSelector((s) => s.editor.previewMode);

  useEffect(() => {
    if (draft?.course_id === remoteCourse.course_id) return;
    dispatch(openDraft(remoteCourse));
  }, [dispatch, draft?.course_id, remoteCourse.course_id]); // eslint-disable-line react-hooks/exhaustive-deps -- remoteCourse 对象引用被排除：只对 course_id 变化响应，避免无关 prop 更新重复打开草稿

  const firstLesson = draft?.lessons[0];
  const firstPage = firstLesson?.pages[0];

  const [selectedLessonId, setSelectedLessonId] = useState<string | null>(
    firstLesson?.lesson_id ?? null,
  );
  const [selectedPageId, setSelectedPageId] = useState<string | null>(
    firstPage?.page_id ?? null,
  );
  const [libraryQuery, setLibraryQuery] = useState('');
  const [expandedSectionIds, setExpandedSectionIds] = useState<Set<(typeof BLOCK_CATEGORIES)[number]['id']>>(
    () => new Set(BLOCK_CATEGORIES.map((category) => category.id)),
  );

  useEffect(() => {
    if (!draft || draft.lessons.length === 0) {
      if (selectedLessonId !== null) setSelectedLessonId(null);
      if (selectedPageId !== null) setSelectedPageId(null);
      return;
    }

    const lesson =
      draft.lessons.find((item) => item.lesson_id === selectedLessonId) ?? draft.lessons[0];
    const page =
      lesson?.pages.find((item) => item.page_id === selectedPageId) ?? lesson?.pages[0];

    if (lesson && lesson.lesson_id !== selectedLessonId) {
      setSelectedLessonId(lesson.lesson_id);
    }

    if (page && page.page_id !== selectedPageId) {
      setSelectedPageId(page.page_id);
    }
  }, [draft, selectedLessonId, selectedPageId]);

  useEffect(() => {
    if (!draft || draft.lessons.length > 0) return;

    const lessonId = uuid();
    const pageId = nanoid();
    dispatch(addLesson({ lessonId, pageId, title: 'Lesson 1' }));
    setSelectedLessonId(lessonId);
    setSelectedPageId(pageId);
  }, [dispatch, draft]);

  const selectedLesson =
    draft?.lessons.find((lesson) => lesson.lesson_id === selectedLessonId) ?? null;
  const selectedPage =
    selectedLesson?.pages.find((page) => page.page_id === selectedPageId) ?? null;

  const librarySections = BLOCK_CATEGORIES.map((category) => {
    const query = libraryQuery.trim().toLowerCase();
    const blocks = (Object.entries(BLOCK_META) as [BlockType, (typeof BLOCK_META)[BlockType]][])
      .filter(([, meta]) => meta.category === category.id)
      .filter(([type, meta]) => {
        if (!query) return true;
        return (
          meta.label.toLowerCase().includes(query) ||
          category.label.toLowerCase().includes(query) ||
          type.toLowerCase().includes(query)
        );
      });

    return {
      ...category,
      blocks,
    };
  }).filter((section) => section.blocks.length > 0);

  function setActiveLocation(lessonId: string, pageId: string) {
    setSelectedLessonId(lessonId);
    setSelectedPageId(pageId);
    dispatch(selectBlock(null));
  }

  function handleAddPage() {
    if (!selectedLessonId || !selectedLesson) return;
    const pageId = nanoid();
    dispatch(addPage({ lessonId: selectedLessonId, pageId }));
    setActiveLocation(selectedLessonId, pageId);
  }

  function handleInsertBlock(type: BlockType) {
    if (!selectedLessonId || !selectedPageId || !selectedPage) return;
    const blockId = nanoid();

    dispatch(
        addBlock({
          lessonId: selectedLessonId,
          pageId: selectedPageId,
          block: {
            id: blockId,
            type,
            position: { order: selectedPage.blocks.length },
            content: BLOCK_META[type].defaultContent,
            visibilityRule: getDefaultVisibilityRule(selectedPage.blocks.length),
          },
        }),
      );

    dispatch(selectBlock(blockId));
  }

  function toggleLibrarySection(sectionId: (typeof BLOCK_CATEGORIES)[number]['id']) {
    setExpandedSectionIds((current) => {
      const next = new Set(current);
      if (next.has(sectionId)) {
        next.delete(sectionId);
      } else {
        next.add(sectionId);
      }
      return next;
    });
  }

  if (!draft) {
    return (
      <div className="editor-studio">
        <div className="editor-studio__loading">
          <p>Loading editor…</p>
        </div>
      </div>
    );
  }

  return (
    <div className="editor-studio">
      <div className="editor-studio__shell">
        <EditorHeader
          activeLessonId={selectedLessonId}
          activePageId={selectedPageId}
          activeLessonTitle={selectedLesson?.title ?? null}
        />

        <div className="editor-studio__body">
          <aside className="editor-panel editor-library" aria-label="Block library">
            <div className="editor-library__header">
              <h2>Block Library</h2>
            </div>

            <label className="editor-library__search">
              <MagnifyingGlassIcon className="h-4 w-4" />
              <input
                type="search"
                placeholder="Search blocks"
                value={libraryQuery}
                onChange={(event) => setLibraryQuery(event.target.value)}
                aria-label="Search blocks"
              />
            </label>

            <div className="editor-library__sections">
              {librarySections.length > 0 ? (
                librarySections.map((section) => (
                  <section key={section.id} className="editor-library__section">
                    <button
                      type="button"
                      className="editor-library__section-toggle"
                      onClick={() => toggleLibrarySection(section.id)}
                      aria-expanded={expandedSectionIds.has(section.id)}
                      aria-controls={`editor-library-section-${section.id}`}
                    >
                      <div className="editor-library__section-header">
                        <h3>{section.label}</h3>
                      </div>
                      <ChevronDownIcon
                        className={`editor-library__section-chevron ${expandedSectionIds.has(section.id) ? 'is-expanded' : ''}`}
                      />
                    </button>
                    {expandedSectionIds.has(section.id) ? (
                      <div
                        id={`editor-library-section-${section.id}`}
                        className="editor-library__block-grid"
                      >
                        {section.blocks.map(([type, meta]) => (
                          <button
                            key={type}
                            type="button"
                            className="editor-library__block"
                            onClick={() => handleInsertBlock(type)}
                            aria-label={`Add ${meta.label}`}
                          >
                            <span className="editor-library__block-mark" aria-hidden>
                              {meta.icon}
                            </span>
                            <span className="editor-library__block-copy">
                              <strong>{meta.label}</strong>
                            </span>
                          </button>
                        ))}
                      </div>
                    ) : null}
                  </section>
                ))
              ) : (
                <div className="editor-library__empty">
                  <p>No blocks match “{libraryQuery.trim()}”.</p>
                  <button
                    type="button"
                    className="editor-chip editor-chip--ghost"
                    onClick={() => setLibraryQuery('')}
                  >
                    Clear search
                  </button>
                </div>
              )}
            </div>
          </aside>

          {previewMode && selectedLessonId && selectedPageId ? (
            <div className="editor-panel editor-preview-shell">
              <CanvasNavigator
                draft={draft}
                selectedLessonId={selectedLessonId}
                selectedPageId={selectedPageId}
                onSelectPage={(pageId) => setActiveLocation(selectedLessonId, pageId)}
                onAddPage={handleAddPage}
              />
              <PreviewMode
                lessonId={selectedLessonId}
                pageId={selectedPageId}
                onSelectPage={(pageId) => setActiveLocation(selectedLessonId, pageId)}
              />
            </div>
          ) : (
            <>
              <main className="editor-panel editor-canvas-shell">
                <CanvasNavigator
                  draft={draft}
                  selectedLessonId={selectedLessonId}
                  selectedPageId={selectedPageId}
                  onSelectPage={(pageId) => {
                    if (!selectedLessonId) return;
                    setActiveLocation(selectedLessonId, pageId);
                  }}
                  onAddPage={handleAddPage}
                />

                {selectedLessonId && selectedPageId ? (
                  <>
                    <BlockCanvas
                      lessonId={selectedLessonId}
                      pageId={selectedPageId}
                      showAddMenu={false}
                    />
                  </>
                ) : (
                  <div className="editor-canvas-shell__empty">
                    <p>Select a lesson and page to start editing.</p>
                  </div>
                )}
              </main>

              <aside className="editor-panel editor-inspector" aria-label="Properties">
                <div className="editor-inspector__intro">
                  <h2>Properties</h2>
                </div>
                {selectedLessonId && selectedPageId ? (
                  <PropertyPanel lessonId={selectedLessonId} pageId={selectedPageId} />
                ) : null}
              </aside>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

interface CanvasNavigatorProps {
  draft: Course;
  selectedLessonId: string | null;
  selectedPageId: string | null;
  onSelectPage: (pageId: string) => void;
  onAddPage: () => void;
}

function CanvasNavigator({
  draft,
  selectedLessonId,
  selectedPageId,
  onSelectPage,
  onAddPage,
}: CanvasNavigatorProps) {
  const selectedLesson =
    draft.lessons.find((lesson) => lesson.lesson_id === selectedLessonId) ?? draft.lessons[0];

  return (
    <div className="editor-flowbar">
      <div className="editor-flowbar__row">
        <span className="editor-flowbar__label">Pages</span>
        <div className="editor-flowbar__chips">
          {selectedLesson?.pages.map((page, index) => (
            <button
              key={page.page_id}
              type="button"
              className={
                page.page_id === selectedPageId
                  ? 'editor-chip editor-chip--active'
                  : 'editor-chip'
              }
              onClick={() => onSelectPage(page.page_id)}
              aria-label={`Open page ${index + 1}`}
            >
              {index + 1}
            </button>
          ))}
          <button type="button" className="editor-chip editor-chip--ghost" onClick={onAddPage}>
            <PlusIcon className="h-3.5 w-3.5" />
            New page
          </button>
        </div>
      </div>
    </div>
  );
}

