  }
}

if ([string]::IsNullOrWhiteSpace($env:VITE_SUPABASE_URL) -and -not [string]::IsNullOrWhiteSpace($env:SUPABASE_URL)) {
  [System.Environment]::SetEnvironmentVariable('VITE_SUPABASE_URL', $env:SUPABASE_URL, 'Process')
}

