47	export function sanitizeMindMapTree(root: RawMindMapNode): LegacyMindMapNode {
48	  const state = { count: 0 };
49	
50	  function visit(node: RawMindMapNode, depth: number): LegacyMindMapNode | null {
51	    if (state.count >= MAX_TOTAL_NODES) {
52	      return null;
53	    }
54	
55	    const label = normalizeLabel(node.label);
56	    if (!label) {
57	      return null;
58	    }
59	
60	    state.count += 1;
61	    const sanitized: LegacyMindMapNode = {
62	      id: `node-${crypto.randomUUID()}`,
63	      label,
64	    };
65	
66	    if (depth >= MAX_DEPTH) {
67	      return sanitized;
68	    }
69	
70	    const children: LegacyMindMapNode[] = [];
71	    for (const child of (node.children ?? []).slice(0, MAX_CHILDREN_PER_NODE)) {
72	      const nextChild = visit(child, depth + 1);
73	      if (nextChild) {
74	        children.push(nextChild);
75	      }
76	      if (state.count >= MAX_TOTAL_NODES) {
77	        break;
78	      }
79	    }
80	
81	    if (children.length) {
82	      sanitized.children = children;
83	    }
84	
85	    return sanitized;
86	  }
87	
88	  const sanitizedRoot = visit(root, 0);
89	  if (!sanitizedRoot) {
90	    throw new Error('Mind map root could not be normalized.');
91	  }
92	
93	  return sanitizedRoot;
94	}
