110	      imageUrl: null,
111	      links: [],
112	      documentRefs: [],
113	    };
114	
115	    for (const child of node.children ?? []) {
116	      visit(child, node.id);
117	    }
118	  }
119	
120	  visit(root, null);
121	
122	  return { rootNodeId: root.id, nodes };
123	}
